package com.example.xrealprobe;
import android.app.*; import android.os.*; import android.content.*; import android.hardware.display.*; import android.hardware.usb.*; import android.graphics.*; import android.view.*; import android.widget.*; import java.util.*;
public class MainActivity extends Activity {
 TextView report; DisplayManager dm; Presentation presentation; LinearLayout layout; int scans=0; volatile String hidReport="Not tested"; volatile boolean probing=false; UsbDevice pendingDevice; final String USB_ACTION="com.example.xrealprobe.USB_PERMISSION"; final BroadcastReceiver usbReceiver=new BroadcastReceiver(){public void onReceive(Context ctx,Intent intent){if(USB_ACTION.equals(intent.getAction())){UsbDevice d=pendingDevice;pendingDevice=null;if(d!=null && ((UsbManager)getSystemService(USB_SERVICE)).hasPermission(d))startRead(d);else {hidReport="USB permission denied";scan();}}}}; final Handler handler=new Handler(Looper.getMainLooper()); final Runnable refresh=new Runnable(){public void run(){scan();handler.postDelayed(this,2000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b); dm=(DisplayManager)getSystemService(DISPLAY_SERVICE); layout=new LinearLayout(this);layout.setOrientation(1); ScrollView scroll=new ScrollView(this);scroll.addView(layout);scroll.setOnApplyWindowInsetsListener((v,insets)->{int pad=(int)(12*getResources().getDisplayMetrics().density);android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(safe.left+pad,safe.top+pad,safe.right+pad,safe.bottom+pad);return insets;}); if(android.os.Build.VERSION.SDK_INT<30){scroll.setOnApplyWindowInsetsListener(null);scroll.setFitsSystemWindows(true);scroll.setPadding(16,16,16,16);}setContentView(scroll);scroll.requestApplyInsets();button("Refresh USB / displays",()->{scan();Toast.makeText(this,"Refreshed #"+scans,Toast.LENGTH_SHORT).show();});button("Copy diagnostic report",()->{scan();((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("XREAL",report.getText()));Toast.makeText(this,"Fresh report copied",Toast.LENGTH_SHORT).show();});button("Test live USB HID (10 sec)",()->probeUsb());button("Stereo test on external display",()->showStereo(0));button("Request external display mode",()->chooseMode());button("Stereo test on phone (preview)",()->{setContentView(new Stereo(this));});report=new TextView(this);report.setTextIsSelectable(true);layout.addView(report);if(Build.VERSION.SDK_INT>=33)registerReceiver(usbReceiver,new IntentFilter(USB_ACTION),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(usbReceiver,new IntentFilter(USB_ACTION));scan();}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());layout.addView(b);}
 void scan(){StringBuilder s=new StringBuilder("Refresh #"+(++scans)+" at "+new java.text.SimpleDateFormat("HH:mm:ss.SSS",Locale.US).format(new Date())+"\nUSB devices (descriptors only):\n");UsbManager u=(UsbManager)getSystemService(USB_SERVICE);for(UsbDevice d:u.getDeviceList().values()){s.append(String.format(Locale.US,"VID=%04x PID=%04x interfaces=%d\n",d.getVendorId(),d.getProductId(),d.getInterfaceCount()));for(int i=0;i<d.getInterfaceCount();i++){UsbInterface f=d.getInterface(i);s.append("  interface "+f.getId()+" class="+f.getInterfaceClass()+" subclass="+f.getInterfaceSubclass()+" endpoints="+f.getEndpointCount()+"\n");}}s.append("\nDisplays:\n");for(Display d:dm.getDisplays()){Display.Mode m=d.getMode();s.append(d.getDisplayId()+" "+d.getName()+" "+m.getPhysicalWidth()+"x"+m.getPhysicalHeight()+" @"+m.getRefreshRate()+" mode="+m.getModeId()+"\n");for(Display.Mode mode:d.getSupportedModes())s.append("  supported mode "+mode.getModeId()+": "+mode.getPhysicalWidth()+"x"+mode.getPhysicalHeight()+" @"+mode.getRefreshRate()+"\n");}s.append("\nLive HID test:\n").append(hidReport);report.setText(s);}
 void probeUsb(){if(probing||pendingDevice!=null)return;UsbManager u=(UsbManager)getSystemService(USB_SERVICE);for(UsbDevice d:u.getDeviceList().values())if(d.getVendorId()==0x3318 && d.getProductId()==0x0444){if(u.hasPermission(d))startRead(d);else {pendingDevice=d;hidReport="Waiting for USB permission";Intent i=new Intent(USB_ACTION).setPackage(getPackageName());u.requestPermission(d,PendingIntent.getBroadcast(this,0,i,PendingIntent.FLAG_IMMUTABLE));}scan();return;}hidReport="XREAL not found";scan();}
 void startRead(UsbDevice d){probing=true;hidReport="Reading; gently rotate head during test";new Thread(()->{StringBuilder out=new StringBuilder();UsbManager u=(UsbManager)getSystemService(USB_SERVICE);UsbDeviceConnection conn=null;try{conn=u.openDevice(d);if(conn==null){out.append("openDevice failed");return;}for(int n=0;n<d.getInterfaceCount();n++){UsbInterface f=d.getInterface(n);if(f.getInterfaceClass()!=UsbConstants.USB_CLASS_HID)continue;out.append("interface ").append(f.getId()).append(": ");if(!conn.claimInterface(f,false)){out.append("claim failed (no forced detach)\n");continue;}try{for(int k=0;k<f.getEndpointCount();k++){UsbEndpoint ep=f.getEndpoint(k);if(ep.getDirection()!=UsbConstants.USB_DIR_IN||ep.getType()!=UsbConstants.USB_ENDPOINT_XFER_INT)continue;int count=0,changed=0;byte[] prev=null,buf=new byte[Math.max(1,Math.min(4096,ep.getMaxPacketSize()))];String first="",last="";long end=SystemClock.elapsedRealtime()+5000;while(SystemClock.elapsedRealtime()<end&&!isFinishing()){int got=conn.bulkTransfer(ep,buf,buf.length,200);if(got>0){byte[] data=Arrays.copyOf(buf,got);StringBuilder h=new StringBuilder();for(int b=0;b<Math.min(got,64);b++)h.append(String.format(Locale.US,"%02x",data[b]&255));last=h.toString();if(count==0)first=last;if(prev!=null&&!Arrays.equals(prev,data))changed++;prev=data;count++;}}out.append(" endpoint ").append(ep.getAddress()).append(" packets=").append(count).append(" changed=").append(changed).append(" first=").append(first).append(" last=").append(last).append("\n");}}finally{conn.releaseInterface(f);}}}catch(Exception e){out.append(e.toString());}finally{if(conn!=null)conn.close();hidReport=out.toString();probing=false;runOnUiThread(()->{if(!isFinishing())scan();});}}).start();}
 void chooseMode(){Display[] ds=dm.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION);if(ds.length==0){Toast.makeText(this,"No external display",Toast.LENGTH_SHORT).show();return;}Display.Mode[] modes=ds[0].getSupportedModes();String[] labels=new String[modes.length];for(int i=0;i<modes.length;i++){Display.Mode m=modes[i];labels[i]=m.getPhysicalWidth()+"x"+m.getPhysicalHeight()+" @"+m.getRefreshRate()+" (mode "+m.getModeId()+")";}new AlertDialog.Builder(this).setTitle("Request display mode (not guaranteed)").setItems(labels,(dialog,i)->showStereo(modes[i].getModeId())).show();}
 void showStereo(int modeId){Display[] ds=dm.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION);if(ds.length==0){Toast.makeText(this,"No external presentation display; try desktop mode",Toast.LENGTH_LONG).show();return;}if(presentation!=null)presentation.dismiss();presentation=new Presentation(this,ds[0]);presentation.setContentView(new Stereo(presentation.getContext()));presentation.show();if(modeId!=0 && presentation.getWindow()!=null){WindowManager.LayoutParams a=presentation.getWindow().getAttributes();a.preferredDisplayModeId=modeId;presentation.getWindow().setAttributes(a);}new Handler(Looper.getMainLooper()).postDelayed(()->{if(!isFinishing())scan();},1500);}
 @Override protected void onResume(){super.onResume();handler.removeCallbacks(refresh);handler.post(refresh);}
 @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
 @Override protected void onDestroy(){unregisterReceiver(usbReceiver);handler.removeCallbacks(refresh);if(presentation!=null)presentation.dismiss();super.onDestroy();}
 static class Stereo extends View {Paint p=new Paint(3);long t=SystemClock.uptimeMillis();Stereo(Context c){super(c);}void line(Canvas c,float x,float y,float a,float b,int color,float w){p.setColor(color);p.setStrokeWidth(w);c.drawLine(x,y,a,b,p);} @Override protected void onDraw(Canvas c){c.drawColor(Color.BLACK);float w=getWidth()/2f,h=getHeight();double ang=(SystemClock.uptimeMillis()-t)*.0007;for(int eye=0;eye<2;eye++){c.save();c.clipRect(eye*w,0,(eye+1)*w,h);float cx=(eye+.5f)*w,cy=h*.5f;float scale=Math.min(w,h)*.43f;float[][] pts=new float[8][2];for(int i=0;i<8;i++){double x=((i&1)==0?-1:1)*.48,y=((i&2)==0?-1:1)*.48,z=((i&4)==0?-1:1)*.48;double rx=x*Math.cos(ang)+z*Math.sin(ang),rz=-x*Math.sin(ang)+z*Math.cos(ang)+3;double e=eye==0?-.032:.032;pts[i][0]=cx+(float)(scale*((rx-e)/rz+e/3.0));pts[i][1]=cy+(float)(scale*y/rz);}for(int i=0;i<8;i++)for(int j=0;j<3;j++){int k=i^(1<<j);if(k>i)line(c,pts[i][0],pts[i][1],pts[k][0],pts[k][1],Color.CYAN,4);}p.setColor(Color.WHITE);p.setTextSize(h*.035f);c.drawText(eye==0?"LEFT":"RIGHT",eye*w+20,h*.12f,p);line(c,cx-15,cy,cx+15,cy,Color.GRAY,2);line(c,cx,cy-15,cx,cy+15,Color.GRAY,2);c.restore();}postInvalidateDelayed(16);}}
}